package dev.shadw.olympia.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Cyclops with its own model and texture. Generated by shadw-mod mob. */
public class CyclopsRenderer extends MobRenderer<Cyclops, CyclopsModel.State, CyclopsModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("olympia", "textures/entity/cyclops.png");

	public CyclopsRenderer(EntityRendererProvider.Context context) {
		super(context, new CyclopsModel(context.bakeLayer(CyclopsModel.LAYER)), 0.8F);
	}

	@Override
	public CyclopsModel.State createRenderState() {
		return new CyclopsModel.State();
	}

	@Override
	public void extractRenderState(Cyclops entity, CyclopsModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(CyclopsModel.State state) {
		return TEXTURE;
	}
}
